const escApos=v=>String(v||'').replace(/'/g,"''");
const activeCheck=x=>['checked_in','pickup_requested'].includes(x.status);
const dateFmt=(iso,locale='es')=>{try{return new Intl.DateTimeFormat(locale==='en'?'en-US':'es-US',{weekday:'long',month:'long',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(`${iso}T12:00:00Z`));}catch{return iso;}};
const timeFmt=(tm,locale='es')=>{if(!tm)return '';const [h,m]=tm.split(':').map(Number);return new Intl.DateTimeFormat(locale==='en'?'en-US':'es-US',{hour:'numeric',minute:'2-digit'}).format(new Date(2020,0,1,h,m));};
function reply(es,en,data={}){return {replyEs:es,replyEn:en,...data};}
function currentLocale(req){return req.locale==='en'?'en':'es';}
function memberName(identity){return identity?.member?.fullName||identity?.user?.username||'';}
function isCancel(text){return /^(no|cancel|cancela|cancelar|dejalo|olvidalo|mejor no|no lo hagas|no publiques|no subas|never mind|do not|dont|don t|stop)$/.test(fold(text));}
function isYes(text){return /^(si|yes|ok|okay|confirmar|confirm|hazlo|do it)$/.test(fold(text));}

async function assignmentsMine(req){const all=await myAssignments(req.churchId,req.identity.member.id),settings=await getDoc(tableNames.settings,req.churchId,'church')||{},window=scheduleThreeWeekWindow(settings.timezone||config.defaultTimezone,Number(settings.weekStartsOn??0)),rows=all.filter(a=>a.dateISO>=window.today&&a.dateISO<=window.end);const enriched=[];for(const a of rows){let history=[];if(a.canSelectSongs){try{history=(await songSelectionContext(req.churchId,a,req.identity.member.id)).history.slice(0,5);}catch{}}enriched.push({...a,songHistory:history});}
  if(!rows.length)return reply('No tienes asignaciones programadas durante las próximas tres semanas.','You do not have any assignments scheduled during the next three weeks.',{data:{assignments:[]},actions:[{id:'navigate:schedule',labelEs:'Ver programa',labelEn:'View schedule',kind:'navigate',target:'schedule'}]});
  const loc=currentLocale(req),lines=enriched.map(a=>{const service=loc==='en'?(a.service?.labelEn||a.service?.label):(a.service?.labelEs||a.service?.label),min=loc==='en'?(a.ministry?.labelEn||a.ministry?.label):(a.ministry?.labelEs||a.ministry?.label),songs=a.canSelectSongs&&a.songHistory.length?`\n${loc==='en'?'Recent song history':'Historial reciente de cantos'}: ${a.songHistory.map(h=>`${h.dateISO}: ${h.songs.map(s=>s.titleEn||s.titleEs||s.title).join(', ')}`).join(' · ')}`:'';return `• ${dateFmt(a.dateISO,loc)} — ${service||''}${a.service?.startTime?` ${timeFmt(a.service.startTime,loc)}`:''}: ${min||a.assignmentKey}${songs}`;});
  const text=lines.join('\n');return loc==='en'?reply('',`Here is what you are assigned during the next three weeks:\n${text}`,{data:{assignments:enriched},actions:[{id:'navigate:schedule',labelEs:'Ver programa',labelEn:'View schedule',kind:'navigate',target:'schedule'}]}):reply(`Esto es lo que te toca durante las próximas tres semanas:\n${text}`,'',{data:{assignments:enriched},actions:[{id:'navigate:schedule',labelEs:'Ver programa',labelEn:'View schedule',kind:'navigate',target:'schedule'}]});}

async function songsHistory(req){const all=await myAssignments(req.churchId,req.identity.member.id),songAssignments=all.filter(a=>a.canSelectSongs).sort((a,b)=>String(b.dateISO).localeCompare(String(a.dateISO))),seen=new Map();for(const a of songAssignments.slice(0,20)){try{const ctx=await songSelectionContext(req.churchId,a,req.identity.member.id);for(const h of ctx.history)if(!seen.has(h.assignmentId))seen.set(h.assignmentId,h);}catch{}}const rows=[...seen.values()].sort((a,b)=>String(b.dateISO).localeCompare(String(a.dateISO))).slice(0,10),loc=currentLocale(req);if(!rows.length)return reply('No encontré historial de cantos para tu cuenta.','I could not find song history for your account.');const text=rows.map(h=>`• ${dateFmt(h.dateISO,loc)}: ${h.songs.map(s=>loc==='en'?(s.titleEn||s.titleEs||s.title):(s.titleEs||s.titleEn||s.title)).join(', ')}`).join('\n');return loc==='en'?reply('',`Your recent song history:\n${text}`):reply(`Tu historial reciente de cantos:\n${text}`,'');}

function contentEventDate(c,timezone){return c.eventDate||parseDateFromText(`${c.titleEs||''} ${c.titleEn||''} ${c.bodyEs||''} ${c.bodyEn||''}`,{timezone});}
function contentEventTime(c){return c.startTime||parseTimeFromText(`${c.titleEs||''} ${c.titleEn||''} ${c.bodyEs||''} ${c.bodyEn||''}`);}
function queryTerms(text){const stop=new Set(['donde','va','a','ser','la','el','los','las','proxima','proximo','cuando','hora','que','dice','anuncio','announcement','where','is','next','when','what','time','the']);return fold(text).split(' ').filter(x=>x.length>2&&!stop.has(x));}
function matchContent(c,terms){const hay=fold(`${c.titleEs||''} ${c.titleEn||''} ${c.bodyEs||''} ${c.bodyEn||''} ${c.category||''} ${(c.tags||[]).join(' ')}`);if(!terms.length)return 1;let score=0;for(const t of terms){if(hay.includes(t))score+=3;else if(hay.split(' ').some(w=>w.length>3&&tokenSimilarity(t,w)>=.78))score+=1;}return score;}
async function announcementsQuery(req,message){const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},tz=settings.timezone||config.defaultTimezone,today=churchDateISO(tz),terms=queryTerms(message),rows=(await listDocs(tableNames.content,req.churchId,{max:1000})).filter(x=>x.published!==false&&['announcement','bulletin'].includes(x.kind));const ranked=rows.map(c=>({...c,_date:contentEventDate(c,tz),_time:contentEventTime(c),_score:matchContent(c,terms)})).filter(x=>x._score>0).sort((a,b)=>{const af=a._date&&a._date>=today?0:1,bf=b._date&&b._date>=today?0:1;return af-bf||String(a._date||'9999').localeCompare(String(b._date||'9999'))||b._score-a._score||String(b.publishedAt).localeCompare(String(a.publishedAt));});if(!ranked.length)return reply('No encontré un anuncio que coincida con esa pregunta.','I could not find an announcement that matches that question.');const c=ranked[0],loc=currentLocale(req),title=loc==='en'?(c.titleEn||c.titleEs||c.title):(c.titleEs||c.titleEn||c.title),wantLocation=/donde|direccion|where|address/.test(fold(message)),wantTime=/hora|time/.test(fold(message)),wantDate=/cuando|fecha|when|date/.test(fold(message));let details=[];if(c._date)details.push(dateFmt(c._date,loc));if(c._time)details.push(timeFmt(c._time,loc));if(c.address)details.push(c.address);const body=loc==='en'?(c.bodyEn||c.bodyEs||c.body):(c.bodyEs||c.bodyEn||c.body);let answer='';if(wantLocation&&c.address)answer=loc==='en'?`${title} will be at ${c.address}${c._date?` on ${dateFmt(c._date,loc)}`:''}${c._time?` at ${timeFmt(c._time,loc)}`:''}.`:`${title} será en ${c.address}${c._date?` el ${dateFmt(c._date,loc)}`:''}${c._time?` a las ${timeFmt(c._time,loc)}`:''}.`;else if(wantTime&&c._time)answer=loc==='en'?`${title} is at ${timeFmt(c._time,loc)}${c._date?` on ${dateFmt(c._date,loc)}`:''}.`:`${title} es a las ${timeFmt(c._time,loc)}${c._date?` el ${dateFmt(c._date,loc)}`:''}.`;else if(wantDate&&c._date)answer=loc==='en'?`${title} is on ${dateFmt(c._date,loc)}${c._time?` at ${timeFmt(c._time,loc)}`:''}.`:`${title} es el ${dateFmt(c._date,loc)}${c._time?` a las ${timeFmt(c._time,loc)}`:''}.`;else answer=`${title}${details.length?` — ${details.join(' · ')}`:''}${body?`\n${body}`:''}`;return loc==='en'?reply('',answer,{data:{content:c},actions:[...(c.address?[{id:'open-map',labelEs:'Abrir en Mapas',labelEn:'Open in Maps',kind:'url',url:`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(c.address)}`}]:[]),{id:'navigate:church',labelEs:'Ver anuncio',labelEn:'View announcement',kind:'navigate',target:'church'}]}):reply(answer,'',{data:{content:c},actions:[...(c.address?[{id:'open-map',labelEs:'Abrir en Mapas',labelEn:'Open in Maps',kind:'url',url:`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(c.address)}`}]:[]),{id:'navigate:church',labelEs:'Ver anuncio',labelEn:'View announcement',kind:'navigate',target:'church'}]});}

async function eventsQuery(req,message){const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},today=churchDateISO(settings.timezone||config.defaultTimezone),terms=queryTerms(message),rows=(await listDocs(tableNames.events,req.churchId,{max:2000})).filter(x=>x.active!==false&&String(x.dateISO||'')>=today).map(x=>({...x,_score:matchContent({titleEs:x.titleEs,titleEn:x.titleEn,bodyEs:x.descriptionEs,bodyEn:x.descriptionEn,category:'event'},terms)})).filter(x=>x._score>0||terms.length===0).sort((a,b)=>String(a.dateISO).localeCompare(String(b.dateISO))||b._score-a._score).slice(0,5),loc=currentLocale(req);if(!rows.length)return reply('No encontré próximos eventos que coincidan.','I could not find matching upcoming events.');const text=rows.map(x=>`• ${loc==='en'?(x.titleEn||x.titleEs):(x.titleEs||x.titleEn)} — ${dateFmt(x.dateISO,loc)}${x.startTime?` · ${timeFmt(x.startTime,loc)}`:''}${x.location?` · ${x.location}`:''}`).join('\n');return loc==='en'?reply('',`Upcoming events:\n${text}`,{actions:[{id:'navigate:events',labelEs:'Ver eventos',labelEn:'View events',kind:'navigate',target:'events'}]}):reply(`Próximos eventos:\n${text}`,'',{actions:[{id:'navigate:events',labelEs:'Ver eventos',labelEn:'View events',kind:'navigate',target:'events'}]});}


function programTerm(text){const f=fold(text);if(/predic|sermon|sermon|meditacion|mensaje/.test(f))return ['meditation','sermon','meditacion'];if(/cantos|canciones|songs|song leader/.test(f))return ['songs','cantos'];if(/vigilancia|seguridad|security/.test(f))return ['security','vigilancia'];if(/comunion|ofrenda|communion|offering/.test(f))return ['communion','comunion','offering','ofrenda'];if(/escritura|scripture/.test(f))return ['scripture','escritura'];if(/bienvenida|welcome/.test(f))return ['welcome','bienvenida'];if(/oracion pastoral|peticiones|pastoral prayer/.test(f))return ['petitions','peticiones','pastoral'];if(/oracion|prayer/.test(f))return ['prayer','oracion'];if(/clase|teacher|maestro/.test(f))return ['class','clase'];if(/anuncios|announcements/.test(f))return ['announcement','anuncios'];return [];}
function serviceTerms(text){const f=fold(text);if(/miercoles|wednesday/.test(f))return ['wednesday','miercoles'];if(/clase dominical|sunday class/.test(f))return ['sunday class','clase dominical'];if(/adoracion|worship|culto/.test(f))return ['worship','adoracion'];if(/domingo|sunday/.test(f))return ['sunday','domingo'];return [];}
async function programQuery(req,message){const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},tz=settings.timezone||config.defaultTimezone,today=churchDateISO(tz),askedDate=parseDateFromText(message,{timezone:tz,todayISO:today}),end=new Date(`${today}T12:00:00Z`);end.setUTCDate(end.getUTCDate()+28);let programs=await listProgramViews(req.churchId,{from:today,to:end.toISOString().slice(0,10)}),svcTerms=serviceTerms(message),assignTerms=programTerm(message),loc=currentLocale(req),f=fold(message);if(askedDate)programs=programs.filter(p=>p.dateISO===askedDate);if(svcTerms.length)programs=programs.filter(p=>{const label=fold(`${p.service?.label||''} ${p.service?.labelEn||''} ${p.service?.labelEs||''}`);if(svcTerms.includes('sunday')||svcTerms.includes('domingo'))return /sunday|domingo/.test(label)||new Date(`${p.dateISO}T12:00:00Z`).getUTCDay()===0;return svcTerms.some(t=>label.includes(t));});if(/predic|sermon|meditacion|mensaje/.test(f)&&programs.length>1)programs=programs.filter(p=>/worship|adoracion|culto/.test(fold(`${p.service?.label||''} ${p.service?.labelEn||''} ${p.service?.labelEs||''}`)))||programs;if(!programs.length)return reply('No encontré un programa que coincida con esa fecha o servicio.','I could not find a program matching that date or service.');const p=programs[0],service=loc==='en'?(p.service?.labelEn||p.service?.label):(p.service?.labelEs||p.service?.label);let items=p.items||[];if(assignTerms.length)items=items.filter(i=>{const label=fold(`${i.label||''} ${i.labelEn||''} ${i.labelEs||''}`);return assignTerms.some(t=>label.includes(t));});if(assignTerms.length&&!items.length)return reply(`Encontré ${service} del ${dateFmt(p.dateISO,loc)}, pero no encontré esa parte del programa.`,`I found ${service} on ${dateFmt(p.dateISO,loc)}, but I could not find that program item.`);const lines=items.map(i=>{const label=loc==='en'?(i.labelEn||i.labelEs||i.label):(i.labelEs||i.labelEn||i.label),names=(i.assignees||[]).map(a=>a.fullName||'').filter(Boolean);return `• ${label}: ${names.join(' & ')|| (loc==='en'?'Unfilled':'Sin asignar')}`;}).join('\n');const intro=loc==='en'?`${service} — ${dateFmt(p.dateISO,loc)}${p.startTime?` at ${timeFmt(p.startTime,loc)}`:''}`:`${service} — ${dateFmt(p.dateISO,loc)}${p.startTime?` a las ${timeFmt(p.startTime,loc)}`:''}`;return loc==='en'?reply('',`${intro}\n${lines}`,{data:{program:p},actions:[{id:'navigate:schedule',labelEs:'Ver programa',labelEn:'View program',kind:'navigate',target:'schedule'}]}):reply(`${intro}\n${lines}`,'',{data:{program:p},actions:[{id:'navigate:schedule',labelEs:'Ver programa',labelEn:'View program',kind:'navigate',target:'schedule'}]});}

async function announcementRowsFor(req,message=''){const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},tz=settings.timezone||config.defaultTimezone,today=churchDateISO(tz),f=fold(message),rows=(await listDocs(tableNames.content,req.churchId,{max:2000})).filter(x=>x.published!==false&&x.kind==='announcement');if(/hoy|today/.test(f))return {rows:rows.filter(x=>x.eventDate===today||(!x.eventDate&&String(x.publishedAt||'').slice(0,10)===today)),today,tz};if(/esta semana|this week/.test(f)){const d=new Date(`${today}T12:00:00Z`),to=new Date(d);to.setUTCDate(d.getUTCDate()+6);const end=to.toISOString().slice(0,10);return {rows:rows.filter(x=>{const date=x.eventDate||String(x.publishedAt||'').slice(0,10);return date>=today&&date<=end;}),today,tz};}return {rows:rows.sort((a,b)=>String(b.publishedAt||'').localeCompare(String(a.publishedAt||''))),today,tz};}
async function announcementsCount(req,message){const {rows}=await announcementRowsFor(req,message),f=fold(message),when=/hoy|today/.test(f)?(req.locale==='en'?'today':'hoy'):(/esta semana|this week/.test(f)?(req.locale==='en'?'this week':'esta semana'):'');const es=`Hay ${rows.length} anuncio${rows.length===1?'':'s'}${when?` ${when}`:''}.`,en=`There ${rows.length===1?'is':'are'} ${rows.length} announcement${rows.length===1?'':'s'}${when?` ${when}`:''}.`;return reply(es,en,{data:{count:rows.length},actions:[{id:'clarify:announcements.list',labelEs:'Ver anuncios',labelEn:'Show announcements',kind:'reply'}]});}
async function announcementsList(req,message){const {rows}=await announcementRowsFor(req,message),loc=currentLocale(req);if(!rows.length)return reply('No encontré anuncios para ese periodo.','I did not find announcements for that period.');const shown=rows.slice(0,10),text=shown.map(x=>{const title=loc==='en'?(x.titleEn||x.titleEs||x.title):(x.titleEs||x.titleEn||x.title),date=x.eventDate?dateFmt(x.eventDate,loc):'';return `• ${title}${date?` — ${date}`:''}${x.startTime?` · ${timeFmt(x.startTime,loc)}`:''}${x.address?` · ${x.address}`:''}`;}).join('\n');return loc==='en'?reply('',`Announcements (${rows.length}):\n${text}`,{actions:[{id:'navigate:church',labelEs:'Abrir anuncios',labelEn:'Open announcements',kind:'navigate',target:'church'}]}):reply(`Anuncios (${rows.length}):\n${text}`,'',{actions:[{id:'navigate:church',labelEs:'Abrir anuncios',labelEn:'Open announcements',kind:'navigate',target:'church'}]});}

async function myRsvp(req){const [events,regs]=await Promise.all([listDocs(tableNames.events,req.churchId,{max:2000}),listDocs(tableNames.eventRegistrations,req.churchId,{filter:`memberId eq '${escApos(req.identity.member.id)}'`,max:2000})]),em=new Map(events.map(e=>[e.id,e])),rows=regs.filter(r=>r.status==='registered').map(r=>({r,e:em.get(r.eventId)})).filter(x=>x.e).sort((a,b)=>String(a.e.dateISO).localeCompare(String(b.e.dateISO))),loc=currentLocale(req);if(!rows.length)return reply('No estás registrado actualmente para ningún evento.','You are not currently registered for any events.');const text=rows.map(({r,e})=>`• ${loc==='en'?(e.titleEn||e.titleEs):(e.titleEs||e.titleEn)} — ${dateFmt(e.dateISO,loc)}${e.startTime?` · ${timeFmt(e.startTime,loc)}`:''}`).join('\n');return loc==='en'?reply('',`Your event registrations:\n${text}`,{actions:[{id:'navigate:events',labelEs:'Ver eventos',labelEn:'View events',kind:'navigate',target:'events'}]}):reply(`Tus confirmaciones de eventos:\n${text}`,'',{actions:[{id:'navigate:events',labelEs:'Ver eventos',labelEn:'View events',kind:'navigate',target:'events'}]});}
async function tasksMine(req){const rows=(await listDocs(tableNames.followUps,req.churchId,{filter:`assignedTo eq '${escApos(req.identity.member.id)}'`,max:1000})).filter(x=>x.status!=='cancelled').sort((a,b)=>String(a.dueDate||'9999').localeCompare(String(b.dueDate||'9999'))),loc=currentLocale(req);if(!rows.length)return reply('No tienes tareas asignadas.','You have no assigned tasks.');const text=rows.map(x=>`• ${x.title}${x.dueDate?` — ${dateFmt(x.dueDate,loc)}`:''} [${x.status}]`).join('\n');return loc==='en'?reply('',`Your tasks:\n${text}`,{actions:[{id:'navigate:tasks',labelEs:'Abrir tareas',labelEn:'Open tasks',kind:'navigate',target:'tasks'}]}):reply(`Tus tareas:\n${text}`,'',{actions:[{id:'navigate:tasks',labelEs:'Abrir tareas',labelEn:'Open tasks',kind:'navigate',target:'tasks'}]});}
async function taskComplete(req,message,state){const rows=(await listDocs(tableNames.followUps,req.churchId,{filter:`assignedTo eq '${escApos(req.identity.member.id)}'`,max:1000})).filter(x=>!['completed','cancelled'].includes(x.status));if(!rows.length)return reply('No tienes tareas pendientes para completar.','You have no pending tasks to complete.');const terms=queryTerms(message),ranked=rows.map(x=>({x,score:matchContent({titleEs:x.title,bodyEs:x.notes},terms)})).sort((a,b)=>b.score-a.score);if(rows.length>1&&(!ranked[0].score||ranked[0].score===ranked[1]?.score)){state.pending={type:'task.complete.select',options:rows.slice(0,8).map(x=>({id:x.id,name:x.title}))};return reply('¿Cuál tarea quieres marcar como completada?','Which task would you like to mark complete?',{pending:true,actions:rows.slice(0,8).map(x=>({id:`task-complete:${x.id}`,labelEs:x.title,labelEn:x.title,kind:'reply'}))});}const x=ranked[0].x;state.pending={type:'task.complete.confirm',taskId:x.id,title:x.title};return reply(`Voy a marcar “${x.title}” como completada. ¿Confirmas?`,`I will mark “${x.title}” complete. Confirm?`,{pending:true,actions:[{id:'task-complete:confirm',labelEs:'Sí, completar',labelEn:'Yes, complete',kind:'reply'},{id:'cancel',labelEs:'Cancelar',labelEn:'Cancel',kind:'reply'}]});}

async function adminTasksQuery(req){const [rows,members]=await Promise.all([listDocs(tableNames.followUps,req.churchId,{max:5000}),listDocs(tableNames.members,req.churchId,{max:5000})]),mm=new Map(members.map(m=>[m.id,m.fullName])),pending=rows.filter(x=>!['completed','cancelled'].includes(x.status)).sort((a,b)=>String(a.dueDate||'9999').localeCompare(String(b.dueDate||'9999')));if(!pending.length)return reply('No hay tareas administrativas pendientes.','There are no pending administrative tasks.');const text=pending.slice(0,15).map(x=>`• ${x.title} — ${mm.get(x.assignedTo)||x.assignedTo||'Sin asignar'}${x.dueDate?` — ${x.dueDate}`:''} [${x.status}]`).join('\n');return reply(`Tareas pendientes (${pending.length}):\n${text}`,`Pending tasks (${pending.length}):\n${text}`);}
async function modulesQuery(req){const {moduleState,moduleCatalog}=await import('../modules/registry.js'),state=await moduleState(req.churchId),loc=currentLocale(req),lines=moduleCatalog.map(m=>`• ${loc==='en'?m.labelEn:m.labelEs}: ${state[m.id]?(loc==='en'?'enabled':'activo'):(loc==='en'?'disabled':'desactivado')}`).join('\n');return loc==='en'?reply('',`Module status:\n${lines}`):reply(`Estado de módulos:\n${lines}`,'');}

function skipWord(v){return /^(no|ninguno|ninguna|sin|skip|none|no message|sin mensaje|omitir)$/.test(fold(v));}
async function findMember(req,text){const rows=(await listDocs(tableNames.members,req.churchId,{max:5000})).filter(m=>m.active!==false),terms=queryTerms(text);const scored=rows.map(m=>{const n=fold(m.fullName||'');let score=0;for(const t of terms){if(n.includes(t))score+=4;else if(n.split(' ').some(w=>tokenSimilarity(t,w)>=.78))score+=1;}return {m,score};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);return scored[0]?.m||null;}
async function announcementCreateStart(state){state.pending={type:'announcement.create.title'};return reply('Claro. ¿Cuál es el título del anuncio?','Sure. What is the announcement title?',{pending:true});}
async function announcementCreatePending(req,message,state,action){const p=state.pending;if(isCancel(message)||action==='cancel'){state.pending=null;return reply('Cancelado. No publiqué el anuncio.','Cancelled. I did not publish the announcement.');}const msg=String(message||'').trim();if(p.type==='announcement.create.title'){if(!msg)return reply('Necesito el título del anuncio.','I need the announcement title.',{pending:true});state.pending={...p,type:'announcement.create.body',title:msg};return reply('¿Qué mensaje quieres incluir? Puedes decir “sin mensaje”.','What message would you like to include? You can say “no message”.',{pending:true});}if(p.type==='announcement.create.body'){state.pending={...p,type:'announcement.create.date',body:skipWord(msg)?'':msg};return reply('¿Tiene fecha? Dime la fecha o di “sin fecha”.','Does it have a date? Tell me the date or say “no date”.',{pending:true});}if(p.type==='announcement.create.date'){const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},date=skipWord(msg)?'':parseDateFromText(msg,{timezone:settings.timezone||config.defaultTimezone});if(!skipWord(msg)&&!date)return reply('No pude identificar la fecha. Por ejemplo: “22 de septiembre” o “sin fecha”.','I could not identify the date. For example: “September 22” or “no date”.',{pending:true});state.pending={...p,type:'announcement.create.time',eventDate:date};return reply('¿A qué hora? Dime la hora o di “sin hora”.','What time? Tell me the time or say “no time”.',{pending:true});}if(p.type==='announcement.create.time'){const tm=skipWord(msg)?'':parseTimeFromText(msg);if(!skipWord(msg)&&!tm)return reply('No pude identificar la hora. Por ejemplo: “2:00 PM” o “sin hora”.','I could not identify the time. For example: “2:00 PM” or “no time”.',{pending:true});state.pending={...p,type:'announcement.create.address',startTime:tm};return reply('¿Cuál es la dirección? Puedes decir “sin dirección”.','What is the address? You can say “no address”.',{pending:true});}if(p.type==='announcement.create.address'){state.pending={...p,type:'announcement.create.confirm',address:skipWord(msg)?'':msg};const q=state.pending;return reply(`Voy a publicar “${q.title}”${q.eventDate?` el ${q.eventDate}`:''}${q.startTime?` a las ${q.startTime}`:''}${q.address?` en ${q.address}`:''}. ¿Publicar ahora?`,`I will publish “${q.title}”${q.eventDate?` on ${q.eventDate}`:''}${q.startTime?` at ${q.startTime}`:''}${q.address?` at ${q.address}`:''}. Publish now?`,{pending:true,actions:[{id:'announcement:publish',labelEs:'Publicar',labelEn:'Publish',kind:'reply'},{id:'cancel',labelEs:'Cancelar',labelEn:'Cancel',kind:'reply'}]});}if(p.type==='announcement.create.confirm'&&(action==='announcement:publish'||isYes(msg))){const doc=await createPublication(req.churchId,{kind:'announcement',titleEs:p.title,titleEn:p.title,bodyEs:p.body||'',bodyEn:p.body||'',eventDate:p.eventDate||'',startTime:p.startTime||'',address:p.address||'',published:true},req.identity.member?.id||'');state.pending=null;return reply(`✅ Anuncio publicado: ${doc.title}.`,`✅ Announcement published: ${doc.title}.`,{actions:[{id:'navigate:church',labelEs:'Ver anuncio',labelEn:'View announcement',kind:'navigate',target:'church'}]});}return null;}
async function eventCreateStart(state){state.pending={type:'event.create.title'};return reply('¿Cuál es el título del evento?','What is the event title?',{pending:true});}
async function eventCreatePending(req,message,state,action){const p=state.pending,msg=String(message||'').trim();if(isCancel(message)||action==='cancel'){state.pending=null;return reply('Cancelado. No creé el evento.','Cancelled. I did not create the event.');}if(p.type==='event.create.title'){state.pending={...p,type:'event.create.date',title:msg};return reply('¿En qué fecha será?','What date will it be?',{pending:true});}if(p.type==='event.create.date'){const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},date=parseDateFromText(msg,{timezone:settings.timezone||config.defaultTimezone});if(!date)return reply('No pude identificar la fecha. Intenta “22 de septiembre”.','I could not identify the date. Try “September 22”.',{pending:true});state.pending={...p,type:'event.create.time',dateISO:date};return reply('¿A qué hora? Puedes decir “sin hora”.','What time? You can say “no time”.',{pending:true});}if(p.type==='event.create.time'){const tm=skipWord(msg)?'':parseTimeFromText(msg);if(!skipWord(msg)&&!tm)return reply('No pude identificar la hora.','I could not identify the time.',{pending:true});state.pending={...p,type:'event.create.location',startTime:tm};return reply('¿Dónde será? Puedes decir “sin lugar”.','Where will it be? You can say “no location”.',{pending:true});}if(p.type==='event.create.location'){state.pending={...p,type:'event.create.confirm',location:skipWord(msg)?'':msg};const q=state.pending;return reply(`Crearé el evento “${q.title}” el ${q.dateISO}${q.startTime?` a las ${q.startTime}`:''}${q.location?` en ${q.location}`:''}. ¿Confirmas?`,`I will create “${q.title}” on ${q.dateISO}${q.startTime?` at ${q.startTime}`:''}${q.location?` at ${q.location}`:''}. Confirm?`,{pending:true,actions:[{id:'event:create-confirm',labelEs:'Crear evento',labelEn:'Create event',kind:'reply'},{id:'cancel',labelEs:'Cancelar',labelEn:'Cancel',kind:'reply'}]});}if(p.type==='event.create.confirm'&&(action==='event:create-confirm'||isYes(msg))){const id=`event_${crypto.randomUUID().replace(/-/g,'').slice(0,16)}`,doc={id,titleEs:p.title,titleEn:p.title,descriptionEs:'',descriptionEn:'',dateISO:p.dateISO,startTime:p.startTime||'',location:p.location||'',capacity:0,active:true,createdAt:nowIso(),createdBy:req.identity.member?.id||''};await putDoc(tableNames.events,req.churchId,id,doc,{dateISO:doc.dateISO,active:true});state.pending=null;return reply(`✅ Evento creado: ${doc.titleEs}.`,`✅ Event created: ${doc.titleEn}.`,{actions:[{id:'navigate:events',labelEs:'Ver eventos',labelEn:'View events',kind:'navigate',target:'events'}]});}return null;}
async function taskCreateStart(state){state.pending={type:'task.create.title'};return reply('¿Cuál es la tarea?','What is the task?',{pending:true});}
async function taskCreatePending(req,message,state,action){const p=state.pending,msg=String(message||'').trim();if(isCancel(message)||action==='cancel'){state.pending=null;return reply('Cancelado. No creé la tarea.','Cancelled. I did not create the task.');}if(p.type==='task.create.title'){state.pending={...p,type:'task.create.assignee',title:msg};return reply('¿A quién quieres asignarla?','Who do you want to assign it to?',{pending:true});}if(p.type==='task.create.assignee'){const m=await findMember(req,msg);if(!m)return reply('No pude identificar al miembro. Escribe su nombre.','I could not identify the member. Type their name.',{pending:true});state.pending={...p,type:'task.create.dueDate',assignedTo:m.id,assignedName:m.fullName};return reply(`Asignaré la tarea a ${m.fullName}. ¿Fecha límite? Puedes decir “sin fecha”.`,`I will assign it to ${m.fullName}. Due date? You can say “no date”.`,{pending:true});}if(p.type==='task.create.dueDate'){const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},date=skipWord(msg)?'':parseDateFromText(msg,{timezone:settings.timezone||config.defaultTimezone});if(!skipWord(msg)&&!date)return reply('No pude identificar la fecha límite.','I could not identify the due date.',{pending:true});state.pending={...p,type:'task.create.confirm',dueDate:date};const q=state.pending;return reply(`Crearé “${q.title}” para ${q.assignedName}${q.dueDate?` con fecha ${q.dueDate}`:''}. ¿Confirmas?`,`I will create “${q.title}” for ${q.assignedName}${q.dueDate?` due ${q.dueDate}`:''}. Confirm?`,{pending:true,actions:[{id:'task:create-confirm',labelEs:'Asignar tarea',labelEn:'Assign task',kind:'reply'},{id:'cancel',labelEs:'Cancelar',labelEn:'Cancel',kind:'reply'}]});}if(p.type==='task.create.confirm'&&(action==='task:create-confirm'||isYes(msg))){const id=`followup_${crypto.randomUUID().replace(/-/g,'').slice(0,16)}`,doc={id,title:p.title,sourceType:'chat_hub',sourceId:'',assignedTo:p.assignedTo,dueDate:p.dueDate||'',status:'open',notes:'',createdAt:nowIso(),createdBy:req.identity.member?.id||''};await putDoc(tableNames.followUps,req.churchId,id,doc,{status:doc.status,assignedTo:doc.assignedTo,dueDate:doc.dueDate});await appendHistory(req.churchId,{eventType:'followup.created',memberId:req.identity.member?.id||'',source:'chat-hub',details:{followUpId:id,assignedTo:doc.assignedTo}});state.pending=null;return reply(`✅ Tarea asignada a ${p.assignedName}.`,`✅ Task assigned to ${p.assignedName}.`);}return null;}

async function upcomingSummary(req){
  const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},tz=settings.timezone||config.defaultTimezone,today=churchDateISO(tz),start=new Date(`${today}T12:00:00Z`),end=new Date(start);end.setUTCDate(end.getUTCDate()+7);const to=end.toISOString().slice(0,10),loc=currentLocale(req),lines=[];
  try{const assignments=(await myAssignments(req.churchId,req.identity.member.id)).filter(a=>a.dateISO>=today&&a.dateISO<=to);for(const a of assignments.slice(0,5))lines.push(`${loc==='en'?'Assignment':'Asignación'}: ${dateFmt(a.dateISO,loc)} · ${loc==='en'?(a.service?.labelEn||a.service?.labelEs):(a.service?.labelEs||a.service?.labelEn)} · ${loc==='en'?(a.ministry?.labelEn||a.ministry?.labelEs||a.assignmentKey):(a.ministry?.labelEs||a.ministry?.labelEn||a.assignmentKey)}`);}catch{}
  try{const content=(await listDocs(tableNames.content,req.churchId,{max:500})).filter(x=>x.published!==false).map(x=>({...x,_date:contentEventDate(x,tz)})).filter(x=>x._date>=today&&x._date<=to).sort((a,b)=>a._date.localeCompare(b._date));for(const c of content.slice(0,5))lines.push(`${loc==='en'?'Church':'Iglesia'}: ${dateFmt(c._date,loc)} · ${loc==='en'?(c.titleEn||c.titleEs):(c.titleEs||c.titleEn)}${c.address?` · ${c.address}`:''}`);}catch{}
  try{const events=(await listDocs(tableNames.events,req.churchId,{max:500})).filter(x=>x.active!==false&&x.dateISO>=today&&x.dateISO<=to).sort((a,b)=>a.dateISO.localeCompare(b.dateISO));for(const e of events.slice(0,5))lines.push(`${loc==='en'?'Event':'Evento'}: ${dateFmt(e.dateISO,loc)} · ${loc==='en'?(e.titleEn||e.titleEs):(e.titleEs||e.titleEn)}${e.location?` · ${e.location}`:''}`);}catch{}
  if(!lines.length)return reply('No encontré asignaciones, anuncios con fecha ni eventos para los próximos siete días.','I did not find assignments, dated announcements, or events for the next seven days.');
  return loc==='en'?reply('',`Here is your Church Hub summary for the next seven days:\n${lines.map(x=>`• ${x}`).join('\n')}`):reply(`Este es tu resumen de Church Hub para los próximos siete días:\n${lines.map(x=>`• ${x}`).join('\n')}`,'');
}

async function prayerPublic(req){const rows=(await listDocs(tableNames.petitions,req.churchId,{max:500})).filter(p=>p.private!==true).sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||''))).slice(0,8),loc=currentLocale(req);if(!rows.length)return reply('No hay peticiones públicas recientes.','There are no recent public prayer requests.');const text=rows.map(p=>`• ${p.memberName||''}: ${p.text}`).join('\n');return loc==='en'?reply('',`Recent public prayer requests:\n${text}`,{actions:[{id:'navigate:petitions',labelEs:'Abrir peticiones',labelEn:'Open prayer requests',kind:'navigate',target:'petitions'}]}):reply(`Peticiones públicas recientes:\n${text}`,'',{actions:[{id:'navigate:petitions',labelEs:'Abrir peticiones',labelEn:'Open prayer requests',kind:'navigate',target:'petitions'}]});}

async function childRows(req){const rows=await listDocs(tableNames.childCheckIns,req.churchId,{filter:`memberId eq '${escApos(req.identity.member.id)}'`,max:300});return rows.filter(activeCheck).sort((a,b)=>String(b.checkInAt||'').localeCompare(String(a.checkInAt||'')));}
function matchChild(rows,message){const text=fold(message);const direct=rows.filter(r=>text.includes(fold(r.childName||''))).filter(r=>r.childName);return direct.length===1?direct[0]:rows.length===1?rows[0]:null;}
async function pickupCode(req,message,state){const rows=await childRows(req);if(!rows.length)return reply('No tienes niños con registro activo en este momento.','You do not have any children currently checked in.');let row=matchChild(rows,message);if(!row&&rows.length>1){state.pending={type:'children.pickupCode',options:rows.map(r=>({id:r.id,name:r.childName}))};return reply('Tienes más de un niño registrado. ¿De cuál necesitas el código?','You have more than one child checked in. Which pickup code do you need?',{pending:true,actions:rows.map(r=>({id:`child-code:${r.id}`,labelEs:r.childName,labelEn:r.childName,kind:'reply'}))});}row=row||rows[0];const recovered=await recoverOrRotatePickupCode(req.churchId,row,req.identity.member.id);await appendHistory(req.churchId,{eventType:'children.pickup_code.viewed',memberId:req.identity.member.id,dateISO:row.dateISO||'',source:'chat-hub',details:{childId:row.childId,checkInId:row.id}});return reply(`El código de recogida para ${row.childName} es ${recovered.code}. Muéstralo al cuidador al recogerlo.${recovered.rotated?' Por seguridad, este código reemplaza al anterior.':''}`,`The pickup code for ${row.childName} is ${recovered.code}. Show it to the caregiver at pickup.${recovered.rotated?' For security, this code replaced the previous one.':''}`,{sensitive:true,data:{childId:row.childId,checkInId:row.id}});}
async function childrenStatus(req){const rows=await childRows(req),loc=currentLocale(req);if(!rows.length)return reply('No tienes niños registrados actualmente en Cuidado de Niños.','You do not currently have any children checked in to Children Care.');const text=rows.map(r=>`• ${r.childName} — ${r.careArea==='nursery'?'Nursery':'Toddlers'} — ${r.status==='pickup_requested'?(loc==='en'?'pickup requested':'recogida solicitada'):(loc==='en'?'checked in':'registrado')}`).join('\n');return loc==='en'?reply('',`Current Children Care status:\n${text}`):reply(`Estado actual de Cuidado de Niños:\n${text}`,'');}
async function pickupRequest(req,message,state){const rows=await childRows(req);if(!rows.length)return reply('No tienes niños registrados actualmente.','You do not currently have any children checked in.');let row=matchChild(rows,message);if(!row&&rows.length>1){state.pending={type:'children.pickupRequest',options:rows.map(r=>({id:r.id,name:r.childName}))};return reply('¿A cuál niño quieres solicitar que preparen para recogida?','Which child would you like to request for pickup?',{pending:true,actions:rows.map(r=>({id:`child-pickup:${r.id}`,labelEs:r.childName,labelEn:r.childName,kind:'reply'}))});}row=row||rows[0];if(row.status==='pickup_requested')return reply(`La recogida de ${row.childName} ya fue solicitada.`,`Pickup has already been requested for ${row.childName}.`);row.status='pickup_requested';row.pickupRequestedAt=nowIso();row.pickupRequestedBy=req.identity.member.id;await putDoc(tableNames.childCheckIns,req.churchId,row.id,row,{memberId:row.memberId,childId:row.childId,status:row.status,dateISO:row.dateISO||'',careArea:row.careArea||''});await appendHistory(req.churchId,{eventType:'children.pickup.requested',memberId:row.memberId,dateISO:row.dateISO||'',source:'chat-hub',details:{childId:row.childId,childName:row.childName,checkInId:row.id}});return reply(`Listo. Se solicitó la recogida de ${row.childName}. El niño permanece bajo cuidado hasta que un cuidador verifique la entrega.`,`Done. Pickup was requested for ${row.childName}. The child remains in care until a caregiver verifies the handoff.`,{actions:[{id:`child-code:${row.id}`,labelEs:'Mostrar código de recogida',labelEn:'Show pickup code',kind:'reply'}]});}

async function replacement(req,message,state){
  const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},today=churchDateISO(settings.timezone||config.defaultTimezone),all=(await myAssignments(req.churchId,req.identity.member.id)).filter(a=>a.dateISO>=today).slice(0,8);
  if(!all.length)return reply('No encontré una asignación próxima para reemplazar.','I could not find an upcoming assignment to replace.');
  const date=parseDateFromText(message,{timezone:settings.timezone||config.defaultTimezone,todayISO:today});let matches=date?all.filter(a=>a.dateISO===date):all;
  if(matches.length!==1){state.pending={type:'replacement.select',options:matches.map(a=>({id:a.id,dateISO:a.dateISO,labelEs:a.ministry?.labelEs||a.ministry?.label||a.assignmentKey,labelEn:a.ministry?.labelEn||a.ministry?.label||a.assignmentKey}))};return reply('¿Para cuál asignación necesitas reemplazo?','Which assignment do you need a replacement for?',{pending:true,actions:matches.map(a=>({id:`replacement:${a.id}`,labelEs:`${a.dateISO} · ${a.ministry?.labelEs||a.ministry?.label||a.assignmentKey}`,labelEn:`${a.dateISO} · ${a.ministry?.labelEn||a.ministry?.label||a.assignmentKey}`,kind:'reply'}))});}
  const a=matches[0];state.pending={type:'replacement.confirm',assignmentId:a.id,dateISO:a.dateISO,labelEs:a.ministry?.labelEs||a.ministry?.label||a.assignmentKey,labelEn:a.ministry?.labelEn||a.ministry?.label||a.assignmentKey};return replacementConfirmation(state.pending);
}
function replacementConfirmation(p){return reply(`Voy a solicitar reemplazo para ${p.labelEs} del ${p.dateISO}. El sistema seleccionará automáticamente a una persona elegible y disponible. ¿Continuar?`,`I will request a replacement for ${p.labelEn} on ${p.dateISO}. The scheduler will automatically select an eligible and available person. Continue?`,{pending:true,requiresConfirmation:true,actions:[{id:'replacement:confirm',labelEs:'Sí, solicitar reemplazo',labelEn:'Yes, request replacement',kind:'reply'},{id:'cancel',labelEs:'Cancelar',labelEn:'Cancel',kind:'reply'}]});}


async function availability(req,message,state){
  const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},tz=settings.timezone||config.defaultTimezone,today=churchDateISO(tz),range=parseDateRangeFromText(message,{timezone:tz,todayISO:today});
  if(!range)return reply('Necesito una fecha o periodo. Por ejemplo: “No estaré disponible el próximo domingo” o “esta semana y la que viene”.','I need a date or period. For example: “I will be unavailable next Sunday” or “this week and next week”.',{needsClarification:true});
  const assigned=(await myAssignments(req.churchId,req.identity.member.id)).filter(a=>range.from<=a.dateISO&&a.dateISO<=range.to);state.pending={type:'availability.confirm',from:range.from,to:range.to,affected:assigned.map(a=>({id:a.id,dateISO:a.dateISO,labelEs:a.ministry?.labelEs||a.ministry?.label||a.assignmentKey,labelEn:a.ministry?.labelEn||a.ministry?.label||a.assignmentKey}))};
  const extra=assigned.length?` Tienes ${assigned.length} asignación(es) dentro de ese periodo; al guardar la ausencia, el sistema procesará sus reemplazos automáticamente.`:'';const extraEn=assigned.length?` You have ${assigned.length} assignment(s) in that period; saving the unavailability will automatically process their replacements.`:'';
  return reply(`Voy a registrar que no estás disponible del ${range.from} al ${range.to}.${extra} ¿Continuar?`,`I will record you as unavailable from ${range.from} through ${range.to}.${extraEn} Continue?`,{pending:true,requiresConfirmation:true,actions:[{id:'availability:confirm',labelEs:'Guardar ausencia',labelEn:'Save unavailability',kind:'reply'},{id:'cancel',labelEs:'Cancelar',labelEn:'Cancel',kind:'reply'}]});
}


async function programStatus(req){const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},today=churchDateISO(settings.timezone||config.defaultTimezone),end=new Date(`${today}T12:00:00Z`);end.setUTCDate(end.getUTCDate()+21);const programs=await listProgramViews(req.churchId,{from:today,to:end.toISOString().slice(0,10)}),loc=currentLocale(req);if(!programs.length)return reply('No hay programas próximos.','There are no upcoming programs.');const text=programs.map(p=>`• ${p.dateISO} ${loc==='en'?(p.service?.labelEn||p.service?.label):(p.service?.labelEs||p.service?.label)} — ${p.readiness.ready?(loc==='en'?'Ready':'Listo'):`${p.readiness.openAssignments} ${loc==='en'?'open':'abiertas'}, ${p.readiness.missingSongs} ${loc==='en'?'missing songs':'cantos pendientes'}`}`).join('\n');return loc==='en'?reply('',`Program status:\n${text}`):reply(`Estado del programa:\n${text}`,'');}
async function pendingSongs(req){const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},today=churchDateISO(settings.timezone||config.defaultTimezone),end=new Date(`${today}T12:00:00Z`);end.setUTCDate(end.getUTCDate()+28);const assignments=await listDocs(tableNames.assignments,req.churchId,{filter:`dateISO ge '${today}' and dateISO le '${end.toISOString().slice(0,10)}'`,max:3000}),members=await listDocs(tableNames.members,req.churchId,{max:5000}),mm=new Map(members.map(m=>[m.id,m])),rows=assignments.filter(a=>a.ministryId==='ministry_songs'&&a.currentMemberId&&a.status!=='unfilled'&&(!Array.isArray(a.songIds)||a.songIds.length===0)).sort((a,b)=>String(a.dateISO).localeCompare(String(b.dateISO)));if(!rows.length)return reply('No hay selecciones de cantos pendientes en las próximas cuatro semanas.','There are no pending song selections in the next four weeks.');const text=rows.map(a=>`• ${a.dateISO} — ${mm.get(a.currentMemberId)?.fullName||a.currentMemberId} (${a.assignmentKey})`).join('\n');return reply(`Cantos pendientes:\n${text}`,`Pending songs:\n${text}`);}
async function memberSearch(req,message){const rows=(await listDocs(tableNames.members,req.churchId,{max:5000})).filter(m=>m.active!==false),terms=queryTerms(message).filter(x=>!['busca','buscar','encuentra','find','search','member','miembro'].includes(x));const scored=rows.map(m=>{const name=fold(m.fullName||'');let score=0;for(const t of terms){if(name.includes(t))score+=3;else if(name.split(' ').some(w=>tokenSimilarity(t,w)>=.78))score+=1;}return {m,score};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,5);if(!scored.length)return reply('No encontré un miembro con ese nombre.','I could not find a member with that name.');const text=scored.map(({m})=>`• ${m.fullName} — ${m.active===false?'inactive':'active'} — ${(m.ministries||[]).join(', ')}`).join('\n');return reply(`Encontré:\n${text}`,`I found:\n${text}`);}

function validateBulletinFile(file){if(!file?.base64)return false;return ['application/pdf','image/jpeg','image/png'].includes(String(file.contentType||'').toLowerCase());}
async function bulletinStart(req,attachment,state){if(attachment&&!validateBulletinFile(attachment))return reply('El boletín debe ser PDF, JPG/JPEG o PNG.','The bulletin must be PDF, JPG/JPEG, or PNG.');state.pending={type:'bulletin.awaitingAttachment',attachment:null};if(attachment){state.pending={type:'bulletin.askMessage',attachment};return reply(`Recibí ${attachment.fileName||'el archivo'}. ¿Quieres agregar un mensaje con el boletín?`,`I received ${attachment.fileName||'the file'}. Would you like to add a message with the bulletin?`,{pending:true,actions:[{id:'bulletin:add-message',labelEs:'Sí, agregar mensaje',labelEn:'Yes, add message',kind:'reply'},{id:'bulletin:no-message',labelEs:'No, publicar solamente',labelEn:'No, publish only',kind:'reply'}]});}return reply('Claro. Adjunta el boletín con el botón +. Acepto PDF, JPG/JPEG o PNG.','Sure. Attach the bulletin with the + button. PDF, JPG/JPEG, and PNG are accepted.',{pending:true,expectsAttachment:true});}
async function bulletinPending(req,message,attachment,state,action){const p=state.pending;if(isCancel(message)||action==='cancel'){state.pending=null;return reply('Cancelado. No se publicó ningún boletín.','Cancelled. No bulletin was published.');}
  if(p.type==='bulletin.awaitingAttachment'){if(!attachment)return reply('Todavía necesito el archivo del boletín. Usa el botón + para adjuntarlo.','I still need the bulletin file. Use the + button to attach it.',{pending:true,expectsAttachment:true});if(!validateBulletinFile(attachment))return reply('El archivo debe ser PDF, JPG/JPEG o PNG.','The file must be PDF, JPG/JPEG, or PNG.',{pending:true,expectsAttachment:true});state.pending={type:'bulletin.askMessage',attachment};return reply(`Recibí ${attachment.fileName}. ¿Quieres agregar un mensaje con el boletín?`,`I received ${attachment.fileName}. Would you like to add a message with the bulletin?`,{pending:true,actions:[{id:'bulletin:add-message',labelEs:'Sí, agregar mensaje',labelEn:'Yes, add message',kind:'reply'},{id:'bulletin:no-message',labelEs:'No, publicar solamente',labelEn:'No, publish only',kind:'reply'}]});}
  if(p.type==='bulletin.askMessage'){const yes=action==='bulletin:add-message'||/^(si|sí|yes|agregar|add)/i.test(message),no=action==='bulletin:no-message'||/^(no|sin mensaje|no message)/i.test(message);if(yes){state.pending={...p,type:'bulletin.awaitingMessage'};return reply('Escribe el mensaje que quieres publicar con el boletín.','Type the message you want to publish with the bulletin.',{pending:true});}if(no){state.pending={...p,type:'bulletin.confirm',message:''};return bulletinSummary(state.pending);}state.pending={...p,type:'bulletin.awaitingMessage'};return bulletinPending(req,message,attachment,state,action);}
  if(p.type==='bulletin.awaitingMessage'){const msg=String(message||'').trim();if(!msg)return reply('Escribe el mensaje o di “sin mensaje”.','Type the message or say “no message”.',{pending:true});state.pending={...p,type:'bulletin.confirm',message:msg};return bulletinSummary(state.pending);}
  if(p.type==='bulletin.confirm'){if(action==='bulletin:publish'||/^(publicar|publish|si|sí|yes)$/i.test(message)){const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},today=churchDateISO(settings.timezone||config.defaultTimezone),doc=await createPublication(req.churchId,{kind:'bulletin',titleEs:`Boletín ${today}`,titleEn:`Bulletin ${today}`,bodyEs:p.message||'',bodyEn:p.message||'',published:true,file:p.attachment},req.identity.member?.id||'');await appendHistory(req.churchId,{eventType:'chat_hub.bulletin_published',memberId:req.identity.member?.id||'',source:'chat-hub',details:{contentId:doc.id,fileName:doc.attachment?.fileName||''}});state.pending=null;return reply(`✅ El boletín fue publicado correctamente${p.message?' con tu mensaje':''}.`,`✅ The bulletin was published successfully${p.message?' with your message':''}.`,{data:{contentId:doc.id},actions:[{id:'navigate:church',labelEs:'Ver boletín',labelEn:'View bulletin',kind:'navigate',target:'church'}]});}return bulletinSummary(p);}
  return null;}
function bulletinSummary(p){return reply(`Voy a publicar:\nBoletín: ${p.attachment?.fileName||'archivo'}\nMensaje: ${p.message||'ninguno'}\n¿Publicar ahora?`,`I will publish:\nBulletin: ${p.attachment?.fileName||'file'}\nMessage: ${p.message||'none'}\nPublish now?`,{pending:true,requiresConfirmation:true,actions:[{id:'bulletin:publish',labelEs:'Publicar',labelEn:'Publish',kind:'reply',danger:false},{id:'cancel',labelEs:'Cancelar',labelEn:'Cancel',kind:'reply'}]});}

function pendingOrdinalAction(message,state){const t=fold(message),opts=state.pending?.options||[];if(!opts.length)return '';let index=-1;if(/^(1|primero|primera|first)$/.test(t))index=0;else if(/^(2|segundo|segunda|second)$/.test(t))index=1;else if(/^(3|tercero|tercera|third)$/.test(t))index=2;else if(/^(4|cuarto|cuarta|fourth)$/.test(t))index=3;if(index<0||!opts[index])return '';const id=opts[index].id;if(state.pending?.type==='replacement.select')return `replacement:${id}`;if(state.pending?.type==='children.pickupCode')return `child-code:${id}`;if(state.pending?.type==='children.pickupRequest')return `child-pickup:${id}`;if(state.pending?.type==='task.complete.select')return `task-complete:${id}`;return '';}

async function handleAction(req,action,state){if(action==='cancel'){state.pending=null;return reply('Cancelado. No hice ningún cambio.','Cancelled. I did not make any changes.');}
  if(action?.startsWith('child-code:')){const id=action.split(':')[1],row=await getDoc(tableNames.childCheckIns,req.churchId,id);if(!row||row.memberId!==req.identity.member.id)return reply('No pude encontrar ese registro activo.','I could not find that active check-in.');state.pending=null;const r=await recoverOrRotatePickupCode(req.churchId,row,req.identity.member.id);return reply(`El código de recogida para ${row.childName} es ${r.code}.`,`The pickup code for ${row.childName} is ${r.code}.`,{sensitive:true});}
  if(action?.startsWith('child-pickup:')){const id=action.split(':')[1],row=await getDoc(tableNames.childCheckIns,req.churchId,id);if(!row||row.memberId!==req.identity.member.id)return reply('No pude encontrar ese registro activo.','I could not find that active check-in.');state.pending=null;return pickupRequest(req,row.childName,state);}
  if(action?.startsWith('replacement:')&&action!=='replacement:confirm'){const id=action.split(':')[1],a=await getDoc(tableNames.assignments,req.churchId,id);if(!a||a.currentMemberId!==req.identity.member.id)return reply('No encontré esa asignación activa en tu cuenta.','I could not find that active assignment on your account.');state.pending={type:'replacement.confirm',assignmentId:a.id,dateISO:a.dateISO,labelEs:a.assignmentKey,labelEn:a.assignmentKey};return replacementConfirmation(state.pending);}
  if(action==='replacement:confirm'&&state.pending?.type==='replacement.confirm'){const p=state.pending;state.pending=null;await requestReplacement(req.churchId,req.identity.member.id,p.assignmentId,{reason:'chat_hub'});return reply('Listo. La solicitud de reemplazo fue procesada.','Done. The replacement request was processed.');}
  if(action==='availability:confirm'&&state.pending?.type==='availability.confirm'){const p=state.pending;state.pending=null;const result=await addUnavailability(req.churchId,req.identity.member.id,{from:p.from,to:p.to,note:'Chat Hub'});return reply(`Listo. Registré tu ausencia del ${p.from} al ${p.to}.${result.affected?` Se procesaron ${result.affected} asignaciones afectadas.`:''}`,`Done. I recorded your unavailability from ${p.from} through ${p.to}.${result.affected?` ${result.affected} affected assignments were processed.`:''}`);}
  if(action?.startsWith('task-complete:')){if(action==='task-complete:confirm'&&state.pending?.type==='task.complete.confirm'){const p=state.pending,row=await getDoc(tableNames.followUps,req.churchId,p.taskId);if(!row||row.assignedTo!==req.identity.member.id)return reply('No encontré esa tarea.','I could not find that task.');row.status='completed';row.updatedAt=nowIso();row.updatedBy=req.identity.member.id;await putDoc(tableNames.followUps,req.churchId,row.id,row,{status:row.status,assignedTo:row.assignedTo||'',dueDate:row.dueDate||''});state.pending=null;return reply(`✅ Tarea completada: ${row.title}.`,`✅ Task completed: ${row.title}.`);}const id=action.split(':')[1],row=await getDoc(tableNames.followUps,req.churchId,id);if(!row||row.assignedTo!==req.identity.member.id)return reply('No encontré esa tarea.','I could not find that task.');state.pending={type:'task.complete.confirm',taskId:row.id,title:row.title};return reply(`Voy a marcar “${row.title}” como completada. ¿Confirmas?`,`I will mark “${row.title}” complete. Confirm?`,{pending:true,actions:[{id:'task-complete:confirm',labelEs:'Sí, completar',labelEn:'Yes, complete',kind:'reply'},{id:'cancel',labelEs:'Cancelar',labelEn:'Cancel',kind:'reply'}]});}
  if(action?.startsWith('announcement:'))return announcementCreatePending(req,'',state,action);
  if(action?.startsWith('event:'))return eventCreatePending(req,'',state,action);
  if(action?.startsWith('task:create'))return taskCreatePending(req,'',state,action);
  if(action?.startsWith('bulletin:'))return bulletinPending(req,'',null,state,action);
  return null;}

export async function executeIntent(req,{intent,message,attachment,state,action}){
  const ordinalAction=!action&&state.pending?pendingOrdinalAction(message,state):'';if(ordinalAction){const r=await handleAction(req,ordinalAction,state);if(r)return r;}
  if(action){const r=await handleAction(req,action,state);if(r)return r;}
  if(state.pending?.type?.startsWith('bulletin.'))return bulletinPending(req,message,attachment,state,action);
  if(state.pending?.type?.startsWith('announcement.create.'))return announcementCreatePending(req,message,state,action);
  if(state.pending?.type?.startsWith('event.create.'))return eventCreatePending(req,message,state,action);
  if(state.pending?.type?.startsWith('task.create.'))return taskCreatePending(req,message,state,action);
  if(isCancel(message)&&state.pending){state.pending=null;return reply('Cancelado. No hice ningún cambio.','Cancelled. I did not make any changes.');}
  if(state.pending?.type==='replacement.confirm'&&isYes(message))return handleAction(req,'replacement:confirm',state);
  if(state.pending?.type==='availability.confirm'&&isYes(message))return handleAction(req,'availability:confirm',state);
  if(state.pending?.type==='task.complete.confirm'&&isYes(message))return handleAction(req,'task-complete:confirm',state);
  switch(intent){
    case 'help': return reply('Puedes preguntarme por tus asignaciones, el programa (por ejemplo quién predica o quién tiene Cantos), reemplazos, disponibilidad, historial de cantos, anuncios y sus fechas/lugares, eventos y RSVP, tus tareas, peticiones públicas y Cuidado de Niños. Los administradores además pueden consultar programas y módulos, buscar miembros, revisar tareas, publicar anuncios, crear eventos, asignar tareas y subir boletines.','You can ask about your assignments, the worship program (for example who is preaching or leading songs), replacements, availability, song history, announcements and their dates/locations, events and RSVPs, your tasks, public prayer requests, and Children Care. Administrators can also inspect programs/modules, search members, review tasks, publish announcements, create events, assign tasks, and upload bulletins.');
    case 'hub.upcomingSummary': return upcomingSummary(req);
    case 'assignments.mine': return assignmentsMine(req);
    case 'program.query': return programQuery(req,message);
    case 'songs.history': return songsHistory(req);
    case 'announcements.count': return announcementsCount(req,message);
    case 'announcements.list': return announcementsList(req,message);
    case 'announcements.query': return announcementsQuery(req,message);
    case 'events.query': return eventsQuery(req,message);
    case 'events.myRsvp': return myRsvp(req);
    case 'tasks.mine': return tasksMine(req);
    case 'tasks.complete': return taskComplete(req,message,state);
    case 'prayer.public': return prayerPublic(req);
    case 'children.pickupCode': return pickupCode(req,message,state);
    case 'children.status': return childrenStatus(req);
    case 'children.pickupRequest': return pickupRequest(req,message,state);
    case 'replacement.request': return replacement(req,message,state);
    case 'availability.add': return availability(req,message,state);
    case 'admin.programStatus': return programStatus(req);
    case 'admin.pendingSongs': return pendingSongs(req);
    case 'admin.memberSearch': return memberSearch(req,message);
    case 'admin.bulletinUpload': return bulletinStart(req,attachment,state);
    case 'admin.announcementCreate': return announcementCreateStart(state);
    case 'admin.eventCreate': return eventCreateStart(state);
    case 'admin.taskCreate': return taskCreateStart(state);
    case 'admin.tasks.query': return adminTasksQuery(req);
    case 'admin.modules.query': return modulesQuery(req);
    default: return null;
  }
}
